//! Codex thread IDs are descriptive links, never credentials or execution grants.
use super::*;
#[derive(Clone,Serialize)]
#[serde(rename_all="camelCase")]
pub(crate) struct Link{pub session_id:String,pub thread_id:Option<String>,pub state:String,pub run_id:Option<String>,pub member_id:Option<String>}
impl RunStore{
 fn codex_schema(&self)->Result<()>{self.db.execute("CREATE TABLE IF NOT EXISTS codex_links(project_id TEXT NOT NULL,session_id TEXT NOT NULL,thread_id TEXT,state TEXT NOT NULL,request_id TEXT NOT NULL,PRIMARY KEY(project_id,session_id),FOREIGN KEY(project_id,session_id) REFERENCES sessions(project_id,id))",&[])?;self.db.execute("CREATE TABLE IF NOT EXISTS codex_member_links(project_id TEXT NOT NULL,session_id TEXT NOT NULL,run_id TEXT NOT NULL,member_id TEXT NOT NULL,PRIMARY KEY(project_id,session_id),UNIQUE(project_id,run_id,member_id),FOREIGN KEY(project_id,session_id) REFERENCES sessions(project_id,id))",&[]).map(|_|())}
 pub(crate) fn codex_links(&self,project:&str)->Result<Vec<Link>>{self.codex_schema()?;self.db.query("SELECT l.session_id,l.thread_id,l.state,m.run_id,m.member_id FROM codex_links l LEFT JOIN codex_member_links m ON m.project_id=l.project_id AND m.session_id=l.session_id WHERE l.project_id=? ORDER BY l.session_id LIMIT 100",&[project.into()])?.into_iter().map(|r|Ok(Link{session_id:r[0].text()?.into(),thread_id:match &r[1]{Value::Null=>None,_=>Some(r[1].text()?.into())},state:r[2].text()?.into(),run_id:match &r[3]{Value::Null=>None,_=>Some(r[3].text()?)},member_id:match &r[4]{Value::Null=>None,_=>Some(r[4].text()?)}})).collect()}
 pub(crate) fn codex_begin(&self,project:&str,session:&str,request:&str,prompt:&str,at:i64,resume:bool)->Result<Option<String>>{self.codex_begin_scoped(project,session,request,prompt,at,resume,None)}
 pub(crate) fn codex_begin_scoped(&self,project:&str,session:&str,request:&str,prompt:&str,at:i64,resume:bool,member:Option<(&str,&str)>)->Result<Option<String>>{
 self.codex_schema()?;self.db.transaction(||{
 let prior=self.db.query("SELECT run_id,member_id FROM codex_member_links WHERE project_id=? AND session_id=?",&[project.into(),session.into()])?;
 if resume{match (prior.first(),member){(None,None)=>{},(Some(row),Some((run,role))) if row[0].text()?==run&&row[1].text()?==role=>{},_=>return Err(StoreError::new("codexMemberMismatch","member thread belongs to another context"))}}
 let thread=if resume{self.writable_session(project,session)?;let rows=self.db.query("SELECT thread_id,state FROM codex_links WHERE project_id=? AND session_id=?",&[project.into(),session.into()])?;let row=rows.first().ok_or_else(StoreError::corrupt)?;if row[1].text()?!="idle"{return Err(StoreError::new("codexUncertain","previous turn must be reconciled; no automatic replay"));}Some(row[0].text()?.to_owned())}else{self.create_session(&Session{project_id:project.into(),id:session.into(),title:"Codex conversation".into(),created_at:at,archived:false,parent_id:None,origin:Origin::Native})?;self.db.execute("INSERT INTO codex_links(project_id,session_id,state,request_id) VALUES(?,?,'idle',?)",&[project.into(),session.into(),request.into()])?;None};
 if !resume{if let Some((run,role))=member{self.db.execute("INSERT INTO codex_member_links(project_id,session_id,run_id,member_id) VALUES(?,?,?,?)",&[project.into(),session.into(),run.into(),role.into()])?;}}
 self.db.execute("UPDATE codex_links SET state='pending',request_id=? WHERE project_id=? AND session_id=?",&[request.into(),project.into(),session.into()])?;
 self.insert_messages(project,session,&[NewMessage{id:format!("{request}-user"),role:Role::User,body:prompt.into(),created_at:at}],Origin::Native)?;Ok(thread)
 })}
 pub(crate) fn codex_remember(&self,project:&str,session:&str,request:&str,thread:&str)->Result<()>{self.db.transaction(||{self.codex_match(project,session,request)?;self.db.execute("UPDATE codex_links SET thread_id=? WHERE project_id=? AND session_id=?",&[thread.into(),project.into(),session.into()]).map(|_|())})}
 fn codex_match(&self,project:&str,session:&str,request:&str)->Result<()>{let rows=self.db.query("SELECT request_id,state FROM codex_links WHERE project_id=? AND session_id=?",&[project.into(),session.into()])?;let row=rows.first().ok_or_else(StoreError::corrupt)?;if row[0].text()?!=request||row[1].text()?!="pending"{return Err(StoreError::new("codexStale","turn ownership changed"));}Ok(())}
 pub(crate) fn codex_finish(&self,project:&str,session:&str,request:&str,text:&str,known:bool,status:&str,at:i64)->Result<()>{self.db.transaction(||{self.codex_match(project,session,request)?;self.insert_messages(project,session,&[NewMessage{id:format!("{request}-assistant"),role:Role::Assistant,body:text.into(),created_at:at},NewMessage{id:format!("{request}-status"),role:Role::System,body:format!("Codex turn: {status}. Completion confirmed: {known}."),created_at:at}],Origin::Native)?;self.db.execute("UPDATE codex_links SET state=? WHERE project_id=? AND session_id=?",&[if known{"idle"}else{"uncertain"}.into(),project.into(),session.into()]).map(|_|())})}
}

#[derive(Clone,Serialize,Deserialize)]#[serde(rename_all="camelCase",deny_unknown_fields)]
pub(crate) struct ModelPreference{pub executable:String,pub model:String,pub effort:String}
impl RunStore{
 fn codex_preferences_schema(&self)->Result<()>{self.db.execute("CREATE TABLE IF NOT EXISTS codex_model_preferences(project_id TEXT NOT NULL,slot TEXT NOT NULL,selection_json TEXT NOT NULL,PRIMARY KEY(project_id,slot))",&[]).map(|_|())}
 pub(crate) fn codex_model_preference(&self,project:&str,slot:&str)->Result<Option<ModelPreference>>{self.codex_preferences_schema()?;let rows=self.db.query("SELECT selection_json FROM codex_model_preferences WHERE project_id=? AND slot=?",&[project.into(),slot.into()])?;rows.first().map(|row|serde_json::from_str(&row[0].text()?).map_err(|_|StoreError::corrupt())).transpose()}
 pub(crate) fn save_codex_model_preference(&self,project:&str,slot:&str,selection:&ModelPreference)->Result<()>{self.codex_preferences_schema()?;let text=serde_json::to_string(selection).map_err(|_|StoreError::corrupt())?;self.db.execute("INSERT INTO codex_model_preferences(project_id,slot,selection_json) VALUES(?,?,?) ON CONFLICT(project_id,slot) DO UPDATE SET selection_json=excluded.selection_json",&[project.into(),slot.into(),text.into()]).map(|_|())}
 pub(crate) fn codex_record_selection(&self,project:&str,session:&str,request:&str,model:&str,effort:Option<&str>,at:i64)->Result<()>{self.codex_match(project,session,request)?;self.insert_messages(project,session,&[NewMessage{id:format!("{request}-model"),role:Role::System,body:format!("Codex model: {model}; reasoning effort: {}; service tier: default (no fast tier requested).",effort.unwrap_or("server default")),created_at:at}],Origin::Native)}
}
